# fmt: on


def build():
    questions = []
    id_counter = 1

    for pool, diff in [(EASY, "Easy"), (MEDIUM, "Medium"), (HARD, "Hard")]:
        for item in pool:
            question, choices, answer, explanation, tags = item
            questions.append({
                **B,
                "id": id_counter,
                "difficulty": diff,
                "question": question,
                "choices": choices,
                "answer": answer,
                "explanation": explanation,
                "tags": tags,
            })
            id_counter += 1

    return questions


if __name__ == "__main__":
    questions = build()
    print(f"Total questions: {len(questions)}")
    print(f"  Easy: {sum(1 for q in questions if q['difficulty'] == 'Easy')}")
    print(f"  Medium: {sum(1 for q in questions if q['difficulty'] == 'Medium')}")
    print(f"  Hard: {sum(1 for q in questions if q['difficulty'] == 'Hard')}")

    OUTPUT.parent.mkdir(parents=True, exist_ok=True)
    with open(OUTPUT, "w", encoding="utf-8") as f:
        for i, q in enumerate(questions):
            line = json.dumps(q, ensure_ascii=False)
            if i == 0:
                f.write("[\n" + line)
            else:
                f.write(",\n" + line)
        f.write("\n]\n")

    print(f"\nWritten to {OUTPUT}")
